import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Readonly exact caller lookup before selecting a source-screen port. */
public final class InspectSourceRangeConsumers {
 public static void main(String[]a)throws Exception{try(var jar=new JarFile(a[0])){for(var e:jar.stream().filter(x->x.getName().endsWith(".class")).toList()){var c=new ClassNode();new ClassReader(jar.getInputStream(e)).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);for(var m:c.methods){boolean uses=m.desc.contains("BattleSpellCatalog$CancellationSpell;");for(var n:m.instructions)if(n instanceof MethodInsnNode call&&call.owner.endsWith("BattleSpellCatalog$CancellationSpell")&&call.name.equals("maximumRange"))uses=true;if(!uses)continue;var lines=new ArrayList<String>();for(var n:m.instructions)if(n instanceof MethodInsnNode call&&(call.name.toLowerCase().contains("range")||call.name.toLowerCase().contains("screen")||call.owner.equals("java/lang/Math")||call.name.contains("Gate")||call.name.toLowerCase().contains("target")))lines.add(call.owner+"."+call.name+call.desc);if(!lines.isEmpty())System.out.println(c.name+"."+m.name+m.desc+"\n "+String.join("\n ",lines));}}}}
}
